<script setup lang="ts">import{onMounted,ref,watch}from'vue';import{Activity,RefreshCw}from'lucide-vue-next';import{api}from'../api';import StatusBadge from'../components/StatusBadge.vue';import EmptyState from'../components/EmptyState.vue';const runs=ref<any[]>([]),status=ref(''),loading=ref(false);async function load(){loading.value=true;runs.value=await api<any[]>(`/api/runs${status.value?`?status=${status.value}`:''}`);loading.value=false}watch(status,load);onMounted(load)</script>
<template><div class="page-heading"><div><span class="eyebrow">自动化</span><h1>运行记录</h1><p>查看部署状态、版本和节点进度。</p></div><button class="btn secondary" @click="load"><RefreshCw/>刷新</button></div><section class="card"><div class="filter-bar"><select v-model="status"><option value="">全部状态</option><option value="queued">等待中</option><option value="running">运行中</option><option value="succeeded">成功</option><option value="failed">失败</option><option value="cancelled">已取消</option></select></div><div v-if="loading" class="skeleton list-skeleton"></div><div v-else class="run-list"><div v-for="r in runs" :key="r.id" class="run-row"><span class="card-icon"><Activity/></span><div class="run-main"><b>{{r.workflow_name||'工作流'}}</b><span>{{r.project_name}} · {{r.version}} · #{{r.id}}</span></div><span>{{r.completed_nodes}} / {{r.node_count}} 节点</span><StatusBadge :status="r.status"/></div><EmptyState v-if="!runs.length" title="没有符合条件的运行"/></div></section></template>
